    e.filePath || e.url || e.download_url || e.file_url || e.fileUrl || e.downloadUrl ||
    e.csv_url || e.csvUrl || e.excel_url || e.excelUrl || e.xlsx_url || e.report_url ||
    e.reportUrl || e.s3_url || e.s3Url || e.signed_url || e.signedUrl ||
    e.presigned_url || e.presignedUrl || e.link || e.location;
